def components(g,bg):
    seen=set(); comps=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j]!=bg and (i,j) not in seen:
                stack=[(i,j)]; comp=[]; seen.add((i,j))
                while stack:
                    r,c=stack.pop(); comp.append((r,c))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            n=(r+dr,c+dc)
                            if 0<=n[0]<len(g) and 0<=n[1]<len(g[0]) and g[n[0]][n[1]]!=bg and n not in seen:
                                seen.add(n); stack.append(n)
                comps.append(comp)
    return comps

def f(g):
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    comps=components(g,bg)
    comps.sort(key=len, reverse=True)
    tmpl=comps[0]
    rs=[r for r,_ in tmpl]; cs=[c for _,c in tmpl]
    cr=(min(rs)+max(rs))//2; cc=(min(cs)+max(cs))//2
    cells=[(r-cr,c-cc,g[r][c]) for r,c in tmpl]
    o=[row[:] for row in g]
    for comp in comps[1:]:
        for r,c in comp:
            for dr,dc,v in cells:
                rr,ccx=r+dr,c+dc
                if 0<=rr<len(o) and 0<=ccx<len(o[0]):
                    o[rr][ccx]=v
    return o

