prog='''from collections import Counter

def comps_fn(grid, bg):
    R, C = len(grid), len(grid[0]); seen = set(); cs = []
    for i in range(R):
        for j in range(C):
            if grid[i][j] != bg and (i, j) not in seen:
                q = [(i, j)]; seen.add((i, j)); cells = []
                while q:
                    a, b = q.pop(); cells.append((a, b))
                    for da in (-1, 0, 1):
                        for db in (-1, 0, 1):
                            x, y = a + da, b + db
                            if 0 <= x < R and 0 <= y < C and grid[x][y] != bg and (x, y) not in seen:
                                seen.add((x, y)); q.append((x, y))
                cs.append(cells)
    cs.sort(key=len, reverse=True); return cs

def transform(grid):
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    cs = comps_fn(grid, bg)
    tmpl = cs[0]; singles = [c[0] for c in cs[1:]]
    tr = min(r for r, c in tmpl); tc = min(c for r, c in tmpl)
    hT = max(r for r, c in tmpl) - tr + 1; wT = max(c for r, c in tmpl) - tc + 1
    trel = {(r - tr, c - tc): grid[r][c] for r, c in tmpl}
    ar, ac = (hT - 1) // 2, (wT - 1) // 2
    out = [row[:] for row in grid]
    for (pr, pc) in singles:
        for (r, c), v in trel.items():
            out[pr - ar + r][pc - ac + c] = v
    return out
'''
